CREATE SET TABLE MDP01_META.META_AREA ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      area_id INTEGER NOT NULL,      area_name VARCHAR(100) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      area_code VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      area_category_id INTEGER NOT NULL,      layer_id INTEGER NOT NULL,      beschreibung VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( area_id )UNIQUE INDEX ( area_code );